/* ============================================================
   saudi-soft-theme — shadcn semantic bridge (Tailwind v4)
   Soft identity: Saudi green (SA), IBM Plex Sans Arabic,
   8/10/12 radius, RTL-ready, light + .dark token rollover.
   ============================================================ */

/* # saudi-soft-theme:start */

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);

  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);

  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);

  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
  --color-status-success: var(--status-success);
  --color-status-warning: var(--status-warning);
  --color-status-info: var(--status-info);
  --color-label: var(--label);
  --color-primary-hover: var(--primary-hover);
  --color-primary-active: var(--primary-active);
  --color-primary-subtle: var(--primary-subtle);

  /* Ladder: sm 8 · md 10 · lg 12 */
  --radius-sm: 0.5rem;
  --radius-md: 0.625rem;
  --radius-lg: 0.75rem;
  --radius-xl: 0.75rem;
  --radius-2xl: 1rem;

  --font-sans: var(--font-sans-soft);

  /* Map Soft elevation → Tailwind shadow-e* utilities */
  --shadow-e1: var(--soft-shadow-e1);
  --shadow-e2: var(--soft-shadow-e2);
  --shadow-e3: var(--soft-shadow-e3);
  --shadow-e4: var(--soft-shadow-e4);
  --shadow-e5: var(--soft-shadow-e5);
  --shadow-e6: var(--soft-shadow-e6);
}

:root {
  /* Layout metrics (app shell) */
  --sidebar-width: 280px;
  --sidebar-collapsed-width: 72px;
  --topbar-height: 64px;

  /* SA scale (active steps) */
  --sa-50: #f3fcf6;
  --sa-100: #dff6e7;
  --sa-200: #b8eacb;
  --sa-300: #88d8ad;
  --sa-400: #54c08a;
  --sa-500: #25935f;
  --sa-600: #1b8354;
  --sa-700: #166a45;
  --sa-800: #14573a;
  --sa-900: #104631;

  /* Neutrals */
  --gray-0: #ffffff;
  --gray-25: #fcfcfd;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-300: #d2d6db;
  --gray-400: #9da4ae;
  --gray-600: #4d5761;
  --gray-700: #384250;
  --gray-900: #111927;
  --gray-950: #0d121c;

  /* shadcn semantic → Soft identity */
  --background: var(--gray-25);
  --foreground: var(--gray-950);

  --card: var(--gray-0);
  --card-foreground: var(--gray-950);

  --popover: var(--gray-0);
  --popover-foreground: var(--gray-950);

  --primary: var(--sa-600);
  --primary-foreground: #ffffff;

  --secondary: var(--sa-700);
  --secondary-foreground: #ffffff;

  --muted: var(--gray-100);
  --muted-foreground: var(--gray-600);

  --accent: var(--sa-500);
  --accent-foreground: #ffffff;

  --destructive: #d92d20;
  --destructive-foreground: #ffffff;

  --border: var(--gray-200);
  --input: var(--gray-200);
  --ring: var(--sa-600);

  /* Base radius = lg (12px); md/sm derived via @theme */
  --radius: 0.75rem;

  --sidebar: var(--gray-0);
  --sidebar-foreground: var(--gray-900);
  --sidebar-primary: var(--sa-600);
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: var(--sa-50);
  --sidebar-accent-foreground: var(--sa-700);
  --sidebar-border: var(--gray-200);
  --sidebar-ring: var(--sa-600);

  --chart-1: var(--sa-600);
  --chart-2: var(--sa-400);
  --chart-3: var(--sa-800);
  --chart-4: var(--sa-300);
  --chart-5: var(--sa-500);

  --success: #079455;
  --warning: #dc6803;
  --info: #1570ef;
  --status-success: var(--success);
  --status-warning: var(--warning);
  --status-info: var(--info);

  --status-success-bg: #ecfdf3;
  --status-success-border: #abefc6;
  --status-warning-bg: #fffaeb;
  --status-warning-border: #fedf89;
  --status-error-bg: #fef3f2;
  --status-error-border: #fecdca;
  --status-info-bg: #eff8ff;
  --status-info-border: #b2ddff;

  --primary-hover: var(--sa-700);
  --primary-active: var(--sa-800);
  --primary-subtle: var(--sa-50);
  --label: var(--gray-700);

  --font-sans-soft: "IBM Plex Sans Arabic", "Work Sans", ui-sans-serif, system-ui,
    sans-serif;
  --font-mono-soft: "Inconsolata", ui-monospace, SFMono-Regular, monospace;

  --overlay: rgb(13 18 28 / 0.4);
  --blur-md: 16px;

  --soft-shadow-e1: 0 1px 2px 0 rgb(16 24 40 / 0.05);
  --soft-shadow-e2: 0 1px 3px 0 rgb(16 24 40 / 0.1), 0 1px 2px 0 rgb(16 24 40 / 0.06);
  --soft-shadow-e3: 0 4px 8px -2px rgb(16 24 40 / 0.1), 0 2px 4px -2px rgb(16 24 40 / 0.06);
  --soft-shadow-e4: 0 12px 16px -4px rgb(16 24 40 / 0.08), 0 4px 6px -2px rgb(16 24 40 / 0.03);
  --soft-shadow-e5: 0 20px 24px -4px rgb(16 24 40 / 0.08), 0 8px 8px -4px rgb(16 24 40 / 0.03);
  --soft-shadow-e6: 0 24px 48px -12px rgb(16 24 40 / 0.18);

  /* Derived from SA ladder — rebrand by replacing --sa-* only */
  --gradient-1: linear-gradient(90deg, var(--sa-600) 0%, var(--sa-500) 100%);
  --gradient-2: linear-gradient(45deg, var(--sa-700) 0%, var(--sa-600) 100%);
  --gradient-primary: var(--gradient-2);
  --gradient-mesh:
    radial-gradient(at 40% 20%, color-mix(in srgb, var(--sa-600) 12%, transparent) 0px, transparent 50%),
    radial-gradient(at 80% 0%, color-mix(in srgb, var(--sa-400) 10%, transparent) 0px, transparent 50%),
    radial-gradient(at 0% 50%, color-mix(in srgb, var(--sa-800) 8%, transparent) 0px, transparent 50%);
}

.dark {
  /* SA lift for contrast on dark surfaces */
  --sa-50: #0c1f16;
  --sa-100: #0f2a1c;
  --sa-200: #14573a;
  --sa-300: #1b8354;
  --sa-400: #25935f;
  --sa-500: #3dba78;
  --sa-600: #3daf6e;
  --sa-700: #2f8f5a;
  --sa-800: #1f6b42;
  --sa-900: #88d8ad;

  /* Gray invert */
  --gray-0: #0b1220;
  --gray-25: #0f1724;
  --gray-50: #141c2b;
  --gray-100: #1c2536;
  --gray-200: #2a3447;
  --gray-300: #3d4a5c;
  --gray-400: #6b7789;
  --gray-600: #b0b8c4;
  --gray-700: #d0d5dd;
  --gray-900: #f0f2f5;
  --gray-950: #ffffff;

  --background: var(--gray-25);
  --foreground: var(--gray-950);

  --card: var(--gray-0);
  --card-foreground: var(--gray-950);

  --popover: var(--gray-0);
  --popover-foreground: var(--gray-950);

  --primary: var(--sa-600);
  --primary-foreground: #0b1220;

  --secondary: var(--sa-700);
  --secondary-foreground: #ffffff;

  --muted: var(--gray-100);
  --muted-foreground: var(--gray-600);

  --accent: var(--sa-500);
  --accent-foreground: #0b1220;

  --destructive: #f04438;
  --destructive-foreground: #ffffff;

  --border: var(--gray-200);
  --input: var(--gray-200);
  --ring: var(--sa-600);

  --sidebar: var(--gray-0);
  --sidebar-foreground: var(--gray-900);
  --sidebar-primary: var(--sa-600);
  --sidebar-primary-foreground: #0b1220;
  --sidebar-accent: var(--sa-50);
  --sidebar-accent-foreground: var(--sa-900);
  --sidebar-border: var(--gray-200);
  --sidebar-ring: var(--sa-600);

  --chart-1: var(--sa-600);
  --chart-2: var(--sa-400);
  --chart-3: var(--sa-300);
  --chart-4: var(--sa-500);
  --chart-5: var(--sa-700);

  --success: #47cd89;
  --warning: #fdb022;
  --info: #53b0fd;
  --status-success: var(--success);
  --status-warning: var(--warning);
  --status-info: var(--info);

  --primary-hover: var(--sa-500);
  --primary-active: var(--sa-700);
  --primary-subtle: var(--sa-50);
  --label: var(--gray-700);

  --status-success-bg: rgb(7 148 85 / 0.15);
  --status-success-border: rgb(71 205 137 / 0.4);
  --status-warning-bg: rgb(220 104 3 / 0.15);
  --status-warning-border: rgb(253 176 34 / 0.4);
  --status-error-bg: rgb(240 68 56 / 0.15);
  --status-error-border: rgb(240 68 56 / 0.4);
  --status-info-bg: rgb(21 112 239 / 0.15);
  --status-info-border: rgb(83 176 253 / 0.4);

  --overlay: rgb(0 0 0 / 0.55);
  --soft-shadow-e1: 0 1px 2px 0 rgb(0 0 0 / 0.3);
  --soft-shadow-e2: 0 2px 4px -1px rgb(0 0 0 / 0.35);
  --soft-shadow-e3: 0 4px 8px -2px rgb(0 0 0 / 0.4);
  --soft-shadow-e4: 0 8px 16px -4px rgb(0 0 0 / 0.45);
  --soft-shadow-e5: 0 16px 32px -8px rgb(0 0 0 / 0.5);
  --soft-shadow-e6: 0 24px 48px -12px rgb(0 0 0 / 0.55);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
  }
}

@layer utilities {
  .bg-gradient-1 {
    background: var(--gradient-1);
  }
  .bg-gradient-2 {
    background: var(--gradient-2);
  }
  .bg-gradient-brand {
    background: var(--gradient-primary);
  }
  .text-gradient {
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }
  .bg-mesh {
    background: var(--gradient-mesh);
  }
}

